INSERT INTO question_bank (question_id, section_code, category_code, level_tag, text, option_a, option_b, option_c, option_d, score_a, score_b, score_c, score_d, active) VALUES
  ($qb$S06C01Q01$qb$, $qb$S06$qb$, $qb$C01$qb$, $qb$L+MM$qb$, $qb$Goals set for employees in your organisation are:$qb$, $qb$Specific, measurable, time-bound, and cascaded from organisational objectives$qb$, $qb$Generally clear — goals exist but vary in specificity and connection to organisational objectives$qb$, $qb$Vague — goals are set but lack measurability or clear connection to outcomes$qb$, $qb$Non-existent or ignored — formal goal setting is not a real management practice$qb$, 5, 3, 2, 1, true),
  ($qb$S06C01Q02$qb$, $qb$S06$qb$, $qb$C01$qb$, $qb$L+MM$qb$, $qb$Organisational goals and individual employee goals are aligned in your organisation:$qb$, $qb$Tightly — every team and individual goal traces directly to an organisational priority$qb$, $qb$Generally — alignment exists at team level but individual goal-to-strategy links are inconsistent$qb$, $qb$Loosely — goals are set but the connection to organisational direction is unclear to most employees$qb$, $qb$Not at all — individual goals are set in isolation with no connection to organisational priorities$qb$, 5, 3, 2, 1, true),
  ($qb$S06C01Q03$qb$, $qb$S06$qb$, $qb$C01$qb$, $qb$MM+E$qb$, $qb$Employees in your organisation understand clearly what they are expected to achieve in the current performance period:$qb$, $qb$Yes — expectations are documented, discussed, and understood by all employees$qb$, $qb$Mostly — most employees understand their priorities but a minority lack clarity$qb$, $qb$Partially — clarity of expectation varies significantly by team and manager$qb$, $qb$No — most employees are unclear about exactly what they are expected to achieve$qb$, 5, 3, 2, 1, true),
  ($qb$S06C01Q04$qb$, $qb$S06$qb$, $qb$C01$qb$, $qb$L+MM$qb$, $qb$The frequency at which goals are reviewed and updated in your organisation is:$qb$, $qb$Quarterly or more frequently — goals are living documents adjusted as conditions change$qb$, $qb$Annually — goals are set once and reviewed at year-end$qb$, $qb$At the start of year only — goals are set but not formally revisited during the year$qb$, $qb$Set but never formally reviewed mid-year$qb$, 5, 3, 2, 1, true),
  ($qb$S06C01Q05$qb$, $qb$S06$qb$, $qb$C01$qb$, $qb$L$qb$, $qb$OKRs (Objectives and Key Results) or an equivalent structured goal framework in your organisation is:$qb$, $qb$Actively used across the organisation with clear ownership and tracking$qb$, $qb$Used in some teams or departments but not universally$qb$, $qb$Being introduced — awareness exists but adoption is incomplete$qb$, $qb$Not in use — no structured goal framework is applied$qb$, 5, 3, 2, 1, true),
  ($qb$S06C01Q06$qb$, $qb$S06$qb$, $qb$C01$qb$, $qb$MM+E$qb$, $qb$When priorities change in your organisation mid-year, goal adjustment for employees is:$qb$, $qb$Fast and communicated — changed priorities are reflected in updated goals within weeks$qb$, $qb$Acknowledged but slow — priority changes trickle into individual goals over months$qb$, $qb$Ignored — employee goals remain unchanged even when organisational priorities have shifted$qb$, $qb$Not managed — employees often work toward goals that are no longer relevant$qb$, 5, 3, 2, 1, true),
  ($qb$S06C01Q07$qb$, $qb$S06$qb$, $qb$C01$qb$, $qb$L+MM$qb$, $qb$Stretch goals (ambitious targets beyond comfortable reach) in your organisation are:$qb$, $qb$Set deliberately and supported — leadership funds and resources ambitious goals$qb$, $qb$Present for some employees and functions but not systematically$qb$, $qb$Rarely set — goals tend toward safe, achievable targets$qb$, $qb$Non-existent — goals are deliberately set to be easily achievable$qb$, 5, 3, 2, 1, true),
  ($qb$S06C01Q08$qb$, $qb$S06$qb$, $qb$C01$qb$, $qb$L+MM$qb$, $qb$Cross-functional goal alignment (ensuring different departments' goals do not conflict) in your organisation is:$qb$, $qb$Actively managed — leadership reviews cross-functional goals for conflict before the year begins$qb$, $qb$Partially managed — obvious conflicts are identified; subtle ones are not$qb$, $qb$Poorly managed — cross-functional goal conflicts are a known source of operational friction$qb$, $qb$Not managed — departments set goals independently with no cross-functional coordination$qb$, 5, 3, 2, 1, true),
  ($qb$S06C01Q09$qb$, $qb$S06$qb$, $qb$C01$qb$, $qb$MM$qb$, $qb$Managers in your organisation have the skills to set high-quality, meaningful goals with their teams:$qb$, $qb$Yes — goal-setting quality is consistently high across the management layer$qb$, $qb$Mostly — most managers set reasonable goals; some lack the skill or commitment$qb$, $qb$Inconsistently — goal quality varies widely and is not a managed standard$qb$, $qb$Poorly — most managers set goals that are either too vague or too easily achievable$qb$, 5, 3, 2, 1, true),
  ($qb$S06C01Q10$qb$, $qb$S06$qb$, $qb$C01$qb$, $qb$L+MM+E$qb$, $qb$The connection between individual goal achievement and career progression in your organisation is:$qb$, $qb$Clear and consistent — achieving goals is demonstrably linked to advancement$qb$, $qb$Generally present — goal achievement matters for progression though other factors also play a role$qb$, $qb$Inconsistent — the link between performance and progression is not always visible$qb$, $qb$Non-existent — career progression appears unrelated to goal achievement in this organisation$qb$, 5, 3, 2, 1, true),
  ($qb$S06C02Q01$qb$, $qb$S06$qb$, $qb$C02$qb$, $qb$L+MM+E$qb$, $qb$Performance reviews in your organisation are:$qb$, $qb$Conducted regularly with genuine depth — not a checkbox exercise$qb$, $qb$Conducted regularly but tend toward form-filling rather than real conversation$qb$, $qb$Conducted infrequently or inconsistently — some managers hold reviews; others do not$qb$, $qb$Not conducted — formal performance review does not happen in any meaningful way$qb$, 5, 3, 2, 1, true),
  ($qb$S06C02Q02$qb$, $qb$S06$qb$, $qb$C02$qb$, $qb$MM+E$qb$, $qb$Employees in your organisation feel that performance reviews are fair and reflect their actual contribution:$qb$, $qb$Yes — most employees feel their review outcome accurately reflects their performance$qb$, $qb$Mostly — some dissatisfaction exists but the majority feel fairly assessed$qb$, $qb$Partially — a significant minority feel their performance is not accurately assessed$qb$, $qb$No — perceived unfairness in performance assessment is a significant organisational problem$qb$, 5, 3, 2, 1, true),
  ($qb$S06C02Q03$qb$, $qb$S06$qb$, $qb$C02$qb$, $qb$L+MM$qb$, $qb$The quality of manager preparation for performance review conversations in your organisation is:$qb$, $qb$High — managers review evidence, gather examples, and prepare specific feedback before each review$qb$, $qb$Moderate — most managers prepare adequately but the depth varies$qb$, $qb$Low — many managers arrive at performance reviews with minimal preparation$qb$, $qb$Very low — performance reviews are improvised conversations without preparation$qb$, 5, 3, 2, 1, true),
  ($qb$S06C02Q04$qb$, $qb$S06$qb$, $qb$C02$qb$, $qb$MM+E$qb$, $qb$Performance review outcomes in your organisation are calibrated across managers:$qb$, $qb$Yes — calibration sessions ensure consistency of standards across different teams$qb$, $qb$Partially — some calibration happens but it is not comprehensive$qb$, $qb$Rarely — different managers apply very different standards with no calibration$qb$, $qb$No — performance ratings are entirely at individual manager discretion with no calibration$qb$, 5, 3, 2, 1, true),
  ($qb$S06C02Q05$qb$, $qb$S06$qb$, $qb$C02$qb$, $qb$L+MM$qb$, $qb$The performance review process in your organisation differentiates meaningfully between high, average, and low performers:$qb$, $qb$Yes — the process produces clear differentiation with meaningful consequences for each level$qb$, $qb$Partially — some differentiation exists but the spread between levels is often compressed$qb$, $qb$Weakly — most employees receive a middle rating regardless of actual performance differences$qb$, $qb$No — the process produces uniform ratings; meaningful differentiation does not occur$qb$, 5, 3, 2, 1, true),
  ($qb$S06C02Q06$qb$, $qb$S06$qb$, $qb$C02$qb$, $qb$L+MM+E$qb$, $qb$The time and effort invested in the performance review process relative to its value is:$qb$, $qb$Well-calibrated — the process produces insight and decisions worth the time invested$qb$, $qb$Slightly heavy — the process takes more time than the value it produces$qb$, $qb$Significantly heavy — it is a bureaucratic burden that consumes time without equivalent value$qb$, $qb$Excessive — the performance review process is widely experienced as a waste of time$qb$, 5, 3, 2, 1, true),
  ($qb$S06C02Q07$qb$, $qb$S06$qb$, $qb$C02$qb$, $qb$L+MM$qb$, $qb$360-degree or multi-source input is used in performance reviews in your organisation:$qb$, $qb$Yes — structured multi-source feedback is systematically gathered and used in reviews$qb$, $qb$Partially — some multi-source input is gathered for some roles or levels$qb$, $qb$Rarely — self-assessment and manager assessment are the only inputs$qb$, $qb$No — performance reviews are based solely on the direct manager's assessment$qb$, 5, 3, 2, 1, true),
  ($qb$S06C02Q08$qb$, $qb$S06$qb$, $qb$C02$qb$, $qb$MM+E$qb$, $qb$After a performance review, employees in your organisation have clarity on:$qb$, $qb$What was assessed, what the rating means, what is expected next, and how to develop further$qb$, $qb$What they were rated and broadly why — but next steps and development are not always clear$qb$, $qb$Their rating — but the conversation was too brief for deeper clarity$qb$, $qb$Very little — performance reviews leave employees unclear about where they stand$qb$, 5, 3, 2, 1, true),
  ($qb$S06C02Q09$qb$, $qb$S06$qb$, $qb$C02$qb$, $qb$L+MM$qb$, $qb$Performance improvement plans (PIPs) or structured underperformance management in your organisation are:$qb$, $qb$Used consistently and constructively — PIPs are genuine development tools with fair timelines and support$qb$, $qb$Used but inconsistently — some managers use them well; others use them as a precursor to exit$qb$, $qb$Rarely used — underperformance is either tolerated or managed informally$qb$, $qb$Not used — formal underperformance management does not exist in this organisation$qb$, 5, 3, 2, 1, true),
  ($qb$S06C02Q10$qb$, $qb$S06$qb$, $qb$C02$qb$, $qb$L$qb$, $qb$The performance management system in your organisation is integrated with compensation, promotion, and development decisions:$qb$, $qb$Yes — performance outcomes directly inform pay, promotion, and development decisions in a transparent way$qb$, $qb$Partially — performance informs some decisions but the link is not consistently applied$qb$, $qb$Weakly — performance review outcomes have limited connection to actual people decisions$qb$, $qb$No — performance reviews and actual people decisions are disconnected processes$qb$, 5, 3, 2, 1, true),
  ($qb$S06C03Q01$qb$, $qb$S06$qb$, $qb$C03$qb$, $qb$MM+E$qb$, $qb$Managers in your organisation provide ongoing performance feedback between formal reviews:$qb$, $qb$Regularly and specifically — employees receive meaningful feedback throughout the year$qb$, $qb$Occasionally — feedback happens when something goes notably right or wrong$qb$, $qb$Rarely — most feedback is reserved for formal review periods$qb$, $qb$Almost never — employees go months without meaningful performance feedback from their manager$qb$, 5, 3, 2, 1, true),
  ($qb$S06C03Q02$qb$, $qb$S06$qb$, $qb$C03$qb$, $qb$MM+E$qb$, $qb$Coaching conversations (exploring how to improve, not just what to improve) in your organisation:$qb$, $qb$Are a regular management practice — managers coach their teams proactively and skillfully$qb$, $qb$Happen with some managers — coaching quality and frequency varies significantly$qb$, $qb$Are rare — most manager feedback is directive rather than coaching-oriented$qb$, $qb$Do not happen — coaching is not a management expectation or practice$qb$, 5, 3, 2, 1, true),
  ($qb$S06C03Q03$qb$, $qb$S06$qb$, $qb$C03$qb$, $qb$L+MM$qb$, $qb$Managers in your organisation are trained in and capable of effective performance coaching:$qb$, $qb$Yes — coaching skills are a defined management competency with training and development investment$qb$, $qb$Some are — coaching capability varies significantly and is not a managed standard$qb$, $qb$Few are — most managers have not received coaching training or development$qb$, $qb$No — coaching is not part of the management capability model in this organisation$qb$, 5, 3, 2, 1, true),
  ($qb$S06C03Q04$qb$, $qb$S06$qb$, $qb$C03$qb$, $qb$MM+E$qb$, $qb$When an employee makes a mistake in your organisation, the typical management response is:$qb$, $qb$Developmental — the manager explores what happened and what the employee learned$qb$, $qb$Balanced — the mistake is addressed but with care for the employee's confidence$qb$, $qb$Blame-oriented — the focus is on who made the mistake rather than what to learn$qb$, $qb$Disproportionate — mistakes generate fear rather than learning$qb$, 5, 3, 2, 1, true),
  ($qb$S06C03Q05$qb$, $qb$S06$qb$, $qb$C03$qb$, $qb$L+MM$qb$, $qb$Real-time performance data (dashboards, productivity metrics, quality scores) available to managers in your organisation is:$qb$, $qb$Comprehensive and used daily — managers have live visibility and act on it continuously$qb$, $qb$Adequate — some data is available but not always current or complete$qb$, $qb$Limited — data arrives with delays that reduce its usefulness for real-time coaching$qb$, $qb$Non-existent — managers have no data tools to support performance coaching$qb$, 5, 3, 2, 1, true),
  ($qb$S06C03Q06$qb$, $qb$S06$qb$, $qb$C03$qb$, $qb$MM+E$qb$, $qb$Employees in your organisation know where they stand relative to expectations at any point in the year:$qb$, $qb$Yes — continuous feedback ensures employees are never surprised by their review outcome$qb$, $qb$Mostly — employees have a reasonable sense of how they are doing$qb$, $qb$Partially — employees have to guess how their performance is perceived between reviews$qb$, $qb$No — review outcomes regularly surprise employees because feedback between reviews is absent$qb$, 5, 3, 2, 1, true),
  ($qb$S06C03Q07$qb$, $qb$S06$qb$, $qb$C03$qb$, $qb$L+MM$qb$, $qb$Performance conversations in your organisation are two-way:$qb$, $qb$Consistently — employees are genuinely heard; their perspective shapes the assessment$qb$, $qb$Mostly — there is dialogue but the manager's view ultimately dominates$qb$, $qb$Rarely — performance conversations are one-directional; managers deliver a verdict$qb$, $qb$Never — performance conversations are notifications, not conversations$qb$, 5, 3, 2, 1, true),
  ($qb$S06C03Q08$qb$, $qb$S06$qb$, $qb$C03$qb$, $qb$MM$qb$, $qb$The relationship between a manager's coaching effectiveness and their team's productivity is:$qb$, $qb$Explicitly recognised — coaching effectiveness is part of how managers are assessed$qb$, $qb$Acknowledged — the link is understood but coaching quality is not formally measured$qb$, $qb$Underappreciated — productivity improvement is sought without investment in management coaching$qb$, $qb$Ignored — no connection is made between manager coaching and team performance$qb$, 5, 3, 2, 1, true),
  ($qb$S06C03Q09$qb$, $qb$S06$qb$, $qb$C03$qb$, $qb$L+MM+E$qb$, $qb$High performers in your organisation receive dedicated coaching and development attention from their managers:$qb$, $qb$Yes — managers invest disproportionately in their highest performers to retain and grow them$qb$, $qb$Partially — high performers get some attention but it is not consistently differentiated$qb$, $qb$Rarely — high performers are often left to manage their own development$qb$, $qb$No — high performers frequently leave because management attention is focused on averages, not excellence$qb$, 5, 3, 2, 1, true),
  ($qb$S06C03Q10$qb$, $qb$S06$qb$, $qb$C03$qb$, $qb$L$qb$, $qb$Investment in management coaching capability (training, supervision, external coaches) in your organisation is:$qb$, $qb$Significant — management coaching is treated as a core organisational capability$qb$, $qb$Moderate — some investment is made but it is not a consistent priority$qb$, $qb$Minimal — occasional training only$qb$, $qb$Non-existent — there is no investment in developing management coaching capability$qb$, 5, 3, 2, 1, true),
  ($qb$S06C04Q01$qb$, $qb$S06$qb$, $qb$C04$qb$, $qb$L+MM$qb$, $qb$Productivity metrics in your organisation are:$qb$, $qb$Clearly defined, measured, and visible to both managers and employees$qb$, $qb$Defined for some roles but not consistently across the organisation$qb$, $qb$Vague — productivity is discussed but not measured in a structured way$qb$, $qb$Non-existent — there are no meaningful productivity metrics$qb$, 5, 3, 2, 1, true),
  ($qb$S06C04Q02$qb$, $qb$S06$qb$, $qb$C04$qb$, $qb$L$qb$, $qb$Leadership in your organisation has real-time visibility into organisational productivity:$qb$, $qb$Yes — dashboards provide live or near-live productivity data at an organisational level$qb$, $qb$Partially — leadership sees productivity data but with a lag that limits real-time response$qb$, $qb$Weakly — productivity data arrives through periodic reports that are often too late to act on$qb$, $qb$No — leadership has no systematic productivity visibility; they rely on manager reports$qb$, 5, 3, 2, 1, true),
  ($qb$S06C04Q03$qb$, $qb$S06$qb$, $qb$C04$qb$, $qb$L+MM$qb$, $qb$The connection between individual productivity and overall organisational performance is:$qb$, $qb$Clearly established and communicated — employees can see how their output connects to business outcomes$qb$, $qb$Generally understood — broad connection is communicated but individual linkage is not always explicit$qb$, $qb$Weak — most employees do not see a clear connection between their daily output and business results$qb$, $qb$Non-existent — productivity is measured but not connected to meaningful business outcomes$qb$, 5, 3, 2, 1, true),
  ($qb$S06C04Q04$qb$, $qb$S06$qb$, $qb$C04$qb$, $qb$MM+E$qb$, $qb$Employees in your organisation who are productive but not visibly busy are:$qb$, $qb$Recognised and rewarded — output is what matters; efficiency is valued$qb$, $qb$Generally recognised — most managers look at outcomes, not just activity$qb$, $qb$Sometimes penalised — some managers confuse visible busyness with productivity$qb$, $qb$Often penalised — the culture rewards visible effort over actual output$qb$, 5, 3, 2, 1, true),
  ($qb$S06C04Q05$qb$, $qb$S06$qb$, $qb$C04$qb$, $qb$L+MM$qb$, $qb$Productivity losses due to poor processes, unnecessary meetings, or administrative burden are:$qb$, $qb$Actively addressed — leadership regularly identifies and eliminates productivity drains$qb$, $qb$Partially addressed — some productivity drains are tackled; others persist$qb$, $qb$Acknowledged but not addressed — productivity drains are known but not prioritised$qb$, $qb$Ignored — productivity-destroying processes are treated as unchangeable organisational fixtures$qb$, 5, 3, 2, 1, true),
  ($qb$S06C04Q06$qb$, $qb$S06$qb$, $qb$C04$qb$, $qb$L+MM$qb$, $qb$Meeting culture in your organisation (frequency, duration, productivity of meetings) is:$qb$, $qb$Healthy — meetings are purposeful, time-boxed, and limited to essential attendees$qb$, $qb$Adequate — some meeting inefficiency exists but it is not a dominant productivity drain$qb$, $qb$Problematic — excessive or poorly run meetings consume significant productive time$qb$, $qb$Severe — meeting culture is one of the most significant sources of productivity loss in this organisation$qb$, 5, 3, 2, 1, true),
  ($qb$S06C04Q07$qb$, $qb$S06$qb$, $qb$C04$qb$, $qb$MM+E$qb$, $qb$Tools and systems provided to employees in your organisation to do their jobs effectively are:$qb$, $qb$Excellent — employees have the tools they need to be maximally productive$qb$, $qb$Good — tools are adequate with some gaps$qb$, $qb$Insufficient — tool gaps are a visible and frustrating source of productivity loss$qb$, $qb$Very poor — employees regularly work around inadequate tools, significantly reducing productivity$qb$, 5, 3, 2, 1, true),
  ($qb$S06C04Q08$qb$, $qb$S06$qb$, $qb$C04$qb$, $qb$L+MM$qb$, $qb$Benchmarking of productivity against industry peers or best practice in your organisation is:$qb$, $qb$Regular — productivity is benchmarked externally and gaps are used to drive improvement$qb$, $qb$Occasional — some external benchmarking happens but not systematically$qb$, $qb$Rare — internal productivity is measured but rarely compared to external standards$qb$, $qb$Never — the organisation has no external productivity benchmark$qb$, 5, 3, 2, 1, true),
  ($qb$S06C04Q09$qb$, $qb$S06$qb$, $qb$C04$qb$, $qb$L+MM+E$qb$, $qb$The impact of remote or hybrid working on productivity in your organisation has been:$qb$, $qb$Neutral or positive — productivity has been maintained or improved through effective management$qb$, $qb$Not applicable — the organisation is fully on-site$qb$, $qb$Somewhat negative — productivity has declined and the causes are partially addressed$qb$, $qb$Significantly negative — remote or hybrid working has damaged productivity and is not being effectively managed$qb$, 5, 3, 2, 1, true),
  ($qb$S06C04Q10$qb$, $qb$S06$qb$, $qb$C04$qb$, $qb$L$qb$, $qb$Investment in productivity improvement (process redesign, technology, workflow analysis) in your organisation is:$qb$, $qb$Deliberate and continuous — productivity improvement is a named organisational priority with budget and ownership$qb$, $qb$Periodic — improvement initiatives happen but are not continuous$qb$, $qb$Reactive — productivity investment happens in response to visible problems rather than proactively$qb$, $qb$Non-existent — no systematic investment is made in improving organisational productivity$qb$, 5, 3, 2, 1, true),
  ($qb$S06C05Q01$qb$, $qb$S06$qb$, $qb$C05$qb$, $qb$L+MM+E$qb$, $qb$The culture of your organisation is:$qb$, $qb$High performance — excellence is expected, resourced, modelled by leadership, and recognised$qb$, $qb$Performance-positive — good performance is valued but not consistently demanded or recognised$qb$, $qb$Average-tolerating — adequate performance is accepted and excellence is not systematically cultivated$qb$, $qb$Performance-averse — high performance stands out but is not structurally supported or rewarded$qb$, 5, 3, 2, 1, true),
  ($qb$S06C05Q02$qb$, $qb$S06$qb$, $qb$C05$qb$, $qb$L+MM+E$qb$, $qb$Standards of quality in work output in your organisation are:$qb$, $qb$High and enforced — poor quality work is addressed; high quality work is recognised$qb$, $qb$Generally high — quality is valued but enforcement is inconsistent$qb$, $qb$Variable — quality standards differ significantly by team, manager, and function$qb$, $qb$Low — poor quality is routinely accepted without consequence$qb$, 5, 3, 2, 1, true),
  ($qb$S06C05Q03$qb$, $qb$S06$qb$, $qb$C05$qb$, $qb$L$qb$, $qb$Leadership in your organisation models high performance standards through their own work:$qb$, $qb$Consistently — leaders are known for the quality and discipline of their own work$qb$, $qb$Mostly — most leaders model high standards; some do not$qb$, $qb$Inconsistently — leadership expectations exceed their own demonstrated standards$qb$, $qb$No — leaders expect performance from others but do not model it themselves$qb$, 5, 3, 2, 1, true),
  ($qb$S06C05Q04$qb$, $qb$S06$qb$, $qb$C05$qb$, $qb$MM+E$qb$, $qb$The consequence of consistently high performance in your organisation (compared to average performance) is:$qb$, $qb$Meaningful and visible — high performers are rewarded, recognised, and promoted more quickly$qb$, $qb$Generally positive — high performance is valued but the differentiation in consequence is modest$qb$, $qb$Minimal — high and average performance produce similar outcomes$qb$, $qb$Non-existent — performance level does not meaningfully affect outcomes in this organisation$qb$, 5, 3, 2, 1, true),
  ($qb$S06C05Q05$qb$, $qb$S06$qb$, $qb$C05$qb$, $qb$L+MM+E$qb$, $qb$The consequence of consistently low performance in your organisation is:$qb$, $qb$Clear and applied — sustained underperformance leads to structured intervention and potential exit$qb$, $qb$Sometimes applied — underperformance is addressed when it becomes severe$qb$, $qb$Rarely applied — low performance is tolerated for extended periods before action is taken$qb$, $qb$Not applied — there is effectively no consequence for sustained low performance$qb$, 5, 3, 2, 1, true),
  ($qb$S06C05Q06$qb$, $qb$S06$qb$, $qb$C05$qb$, $qb$L+MM$qb$, $qb$Performance differentiation in compensation in your organisation is:$qb$, $qb$Significant and felt — high performers earn meaningfully more, reinforcing the value of excellence$qb$, $qb$Moderate — some differentiation exists but is not large enough to be a significant motivator$qb$, $qb$Minimal — pay differences between performance levels are small and not seen as meaningful$qb$, $qb$Non-existent — compensation is largely uniform regardless of performance level$qb$, 5, 3, 2, 1, true),
  ($qb$S06C05Q07$qb$, $qb$S06$qb$, $qb$C05$qb$, $qb$MM+E$qb$, $qb$High performers in your organisation are retained at a higher rate than average performers:$qb$, $qb$Yes — retention data shows that the organisation keeps its best people$qb$, $qb$Mostly — most high performers stay but exceptional talent loss is a recognised issue$qb$, $qb$No — high performer attrition is similar to average performer attrition$qb$, $qb$High performers actually leave at a higher rate — the best people most likely find better opportunities elsewhere$qb$, 5, 3, 2, 1, true),
  ($qb$S06C05Q08$qb$, $qb$S06$qb$, $qb$C05$qb$, $qb$L+MM+E$qb$, $qb$Peer pressure toward high performance (colleagues expecting and encouraging excellence from each other) in your organisation is:$qb$, $qb$Strong and positive — colleagues hold each other to high standards with mutual respect$qb$, $qb$Present in some teams — some teams have strong peer performance norms; others do not$qb$, $qb$Weak — performance norms are set by management, not by peer culture$qb$, $qb$Non-existent or negative — colleagues discourage high performance or excellence makes others uncomfortable$qb$, 5, 3, 2, 1, true),
  ($qb$S06C05Q09$qb$, $qb$S06$qb$, $qb$C05$qb$, $qb$L+MM$qb$, $qb$The organisation's tolerance for mediocrity — accepting below-par performance without intervention — is:$qb$, $qb$Very low — mediocrity is addressed directly and promptly$qb$, $qb$Low — most underperformance is eventually addressed$qb$, $qb$Moderate — significant mediocrity is tolerated for extended periods$qb$, $qb$High — mediocrity is the tolerated norm in this organisation$qb$, 5, 3, 2, 1, true),
  ($qb$S06C05Q10$qb$, $qb$S06$qb$, $qb$C05$qb$, $qb$L+MM+E$qb$, $qb$Overall, the performance culture in your organisation would be described by most employees as:$qb$, $qb$Demanding, fair, and rewarding — high performance is expected and meaningfully recognised$qb$, $qb$Positive but inconsistent — performance is valued but not consistently managed or rewarded$qb$, $qb$Average — adequate performance is the expectation and excellence is not systematically cultivated$qb$, $qb$Poor — there is no real performance culture; output quality is not a consistent management focus$qb$, 5, 3, 2, 1, true),
  ($qb$S06C06Q01$qb$, $qb$S06$qb$, $qb$C06$qb$, $qb$L+MM$qb$, $qb$When an employee's performance falls below expectation, the typical management response time is:$qb$, $qb$Fast (within 2–4 weeks) — underperformance is addressed promptly when it becomes evident$qb$, $qb$Moderate (1–3 months) — underperformance is noticed and eventually addressed$qb$, $qb$Slow (3–6 months) — significant underperformance persists before formal management action$qb$, $qb$Very slow or never — underperformance is tolerated indefinitely without structured intervention$qb$, 5, 3, 2, 1, true),
  ($qb$S06C06Q02$qb$, $qb$S06$qb$, $qb$C06$qb$, $qb$MM+E$qb$, $qb$When underperformance is addressed in your organisation, the process includes:$qb$, $qb$A structured conversation, a written plan with clear expectations and support, and regular follow-up$qb$, $qb$An informal conversation and some monitoring without formal documentation$qb$, $qb$An email or written warning with limited support or follow-up$qb$, $qb$An immediate escalation to HR without a structured performance conversation$qb$, 5, 3, 2, 1, true),
  ($qb$S06C06Q03$qb$, $qb$S06$qb$, $qb$C06$qb$, $qb$L+MM$qb$, $qb$The root cause of underperformance (skill gap, motivation issue, role misfit, personal circumstance) is explored:$qb$, $qb$Always — root cause analysis precedes any intervention decision$qb$, $qb$Usually — root cause is considered before action is taken$qb$, $qb$Rarely — underperformance triggers process without understanding the cause$qb$, $qb$Never — the system treats all underperformance the same regardless of cause$qb$, 5, 3, 2, 1, true),
  ($qb$S06C06Q04$qb$, $qb$S06$qb$, $qb$C06$qb$, $qb$L+MM+E$qb$, $qb$Employees in your organisation who are on a performance improvement plan experience it as:$qb$, $qb$A genuine opportunity to improve with real support — PIPs produce meaningful outcomes in both directions$qb$, $qb$A structured process — fair but primarily administrative$qb$, $qb$A precursor to exit — most employees on PIPs understand they are unlikely to succeed$qb$, $qb$A weapon — PIPs are used to manage people out rather than develop them$qb$, 5, 3, 2, 1, true),
  ($qb$S06C06Q05$qb$, $qb$S06$qb$, $qb$C06$qb$, $qb$L+MM$qb$, $qb$The legal and HR knowledge among managers to manage underperformance correctly is:$qb$, $qb$Strong — managers are trained in and comfortable with the performance management process$qb$, $qb$Adequate — most managers know the basics but rely on HR for guidance$qb$, $qb$Weak — many managers avoid performance management for fear of doing it wrong$qb$, $qb$Very weak — legal uncertainty causes managers to either over-escalate or avoid managing underperformance entirely$qb$, 5, 3, 2, 1, true),
  ($qb$S06C06Q06$qb$, $qb$S06$qb$, $qb$C06$qb$, $qb$MM+E$qb$, $qb$Employees in your organisation who are managed out for underperformance are treated with:$qb$, $qb$Dignity and professionalism — exits from performance management are handled respectfully$qb$, $qb$General adequacy — the process is followed but the human element is not always well-managed$qb$, $qb$Coldly — exits are processed rather than managed with care$qb$, $qb$Poorly — performance management exits damage the individual's dignity and reputation$qb$, 5, 3, 2, 1, true),
  ($qb$S06C06Q07$qb$, $qb$S06$qb$, $qb$C06$qb$, $qb$L+MM$qb$, $qb$The rate at which underperformance intervention results in successful improvement (rather than exit) is:$qb$, $qb$High (over 50%) — PIPs and coaching frequently result in genuine and sustained improvement$qb$, $qb$Moderate (30–50%) — some people improve; others do not$qb$, $qb$Low (under 30%) — performance intervention rarely results in sustained improvement$qb$, $qb$Near zero — performance management is effectively an exit pathway, not a development tool$qb$, 5, 3, 2, 1, true),
  ($qb$S06C06Q08$qb$, $qb$S06$qb$, $qb$C06$qb$, $qb$L+MM$qb$, $qb$Tolerance for underperformance across different parts of the organisation is:$qb$, $qb$Low and consistent — underperformance is managed with similar rigour across all departments$qb$, $qb$Moderate — some variation but generally managed$qb$, $qb$Significantly variable — some departments tolerate underperformance that would not be acceptable elsewhere$qb$, $qb$Extreme — different standards apply in different departments and employees are aware of it$qb$, 5, 3, 2, 1, true),
  ($qb$S06C06Q09$qb$, $qb$S06$qb$, $qb$C06$qb$, $qb$L$qb$, $qb$Senior leadership underperformance is managed with:$qb$, $qb$The same rigour as other levels — senior leaders are held to the same standards$qb$, $qb$Some rigour — serious underperformance at senior level is eventually addressed$qb$, $qb$Less rigour — senior leaders are protected from the processes that apply to others$qb$, $qb$No rigour — senior leader underperformance is effectively unmanaged in this organisation$qb$, 5, 3, 2, 1, true),
  ($qb$S06C06Q10$qb$, $qb$S06$qb$, $qb$C06$qb$, $qb$L+MM+E$qb$, $qb$The overall effectiveness of performance management as a tool for improving individual and team performance is:$qb$, $qb$High — the system produces better performance outcomes and is valued by managers and employees$qb$, $qb$Moderate — the system works adequately but has known limitations$qb$, $qb$Low — the performance management system is more compliance than performance driver$qb$, $qb$Very low — the performance management system is seen as irrelevant or actively harmful$qb$, 5, 3, 2, 1, true),
  ($qb$S06C07Q01$qb$, $qb$S06$qb$, $qb$C07$qb$, $qb$L+MM$qb$, $qb$Work design in your organisation (how work is structured, sequenced, and allocated) is:$qb$, $qb$Deliberate and evidence-based — work is designed to maximise output with minimum unnecessary friction$qb$, $qb$Functional — work design is adequate though not systematically optimised$qb$, $qb$Inherited — most work structures have evolved without deliberate design or review$qb$, $qb$Poor — inefficient work design is a significant and unaddressed productivity problem$qb$, 5, 3, 2, 1, true),
  ($qb$S06C07Q02$qb$, $qb$S06$qb$, $qb$C07$qb$, $qb$L+MM+E$qb$, $qb$Administrative and reporting burden on employees in your organisation is:$qb$, $qb$Minimal — the organisation actively identifies and eliminates non-value-adding administrative tasks$qb$, $qb$Manageable — some administrative overhead exists but does not significantly drain productive capacity$qb$, $qb$Heavy — administrative tasks consume a significant and resented portion of employee time$qb$, $qb$Excessive — bureaucratic burden is a widely cited and unaddressed organisational problem$qb$, 5, 3, 2, 1, true),
  ($qb$S06C07Q03$qb$, $qb$S06$qb$, $qb$C07$qb$, $qb$L+MM$qb$, $qb$Technology adoption to automate repetitive work and free employees for higher-value tasks is:$qb$, $qb$Proactive — the organisation systematically identifies automation opportunities and implements them$qb$, $qb$Selective — some automation exists but the approach is not systematic$qb$, $qb$Slow — automation potential is acknowledged but implementation is delayed or partial$qb$, $qb$Not happening — repetitive manual processes persist without automation investment$qb$, 5, 3, 2, 1, true),
  ($qb$S06C07Q04$qb$, $qb$S06$qb$, $qb$C07$qb$, $qb$MM+E$qb$, $qb$Employees in your organisation have clear processes and systems to follow for their core work activities:$qb$, $qb$Yes — processes are documented, current, and consistently followed$qb$, $qb$Mostly — key processes are documented; some rely on informal knowledge$qb$, $qb$Partially — process documentation is incomplete and inconsistently applied$qb$, $qb$No — most work relies on individual knowledge; processes are not documented or followed consistently$qb$, 5, 3, 2, 1, true),
  ($qb$S06C07Q05$qb$, $qb$S06$qb$, $qb$C07$qb$, $qb$L+MM$qb$, $qb$Continuous improvement culture (employees and managers actively looking for ways to work smarter) in your organisation is:$qb$, $qb$Strong — improvement suggestions are actively solicited, evaluated, and implemented regularly$qb$, $qb$Present — some improvement culture exists but it is not systematic or embedded$qb$, $qb$Weak — improvement is discussed but rarely actioned$qb$, $qb$Absent — the organisation does not have a continuous improvement culture$qb$, 5, 3, 2, 1, true),
  ($qb$S06C07Q06$qb$, $qb$S06$qb$, $qb$C07$qb$, $qb$L+MM$qb$, $qb$Collaboration tools (project management platforms, communication apps, shared workspaces) in your organisation are:$qb$, $qb$Well-integrated and used effectively — tools enhance collaboration without creating additional complexity$qb$, $qb$Adequate — tools exist but are not all used consistently or effectively$qb$, $qb$Fragmented — multiple tools are used inconsistently, creating duplication and confusion$qb$, $qb$Poor — collaboration tool deficiency is a visible productivity problem$qb$, 5, 3, 2, 1, true),
  ($qb$S06C07Q07$qb$, $qb$S06$qb$, $qb$C07$qb$, $qb$MM+E$qb$, $qb$The number of simultaneous priorities assigned to employees in your organisation is:$qb$, $qb$Well-managed — employees typically have 3–5 clear priorities and can focus effectively$qb$, $qb$Somewhat high — employees manage multiple priorities but focus is sometimes fragmented$qb$, $qb$Too high — employees struggle with priority overload and this is visible in quality and speed$qb$, $qb$Extreme — priority overload is a chronic and unresolved productivity problem$qb$, 5, 3, 2, 1, true),
  ($qb$S06C07Q08$qb$, $qb$S06$qb$, $qb$C07$qb$, $qb$L+MM$qb$, $qb$Work hours norms and productivity norms in your organisation:$qb$, $qb$Are healthy and sustainable — hard work is valued but efficiency is rewarded over hours$qb$, $qb$Are generally healthy with some pressure in peak periods$qb$, $qb$Equate long hours with productivity — employees feel pressure to be seen as working regardless of output$qb$, $qb$Create a perverse incentive — the most visibly busy employees are rewarded regardless of their actual output$qb$, 5, 3, 2, 1, true),
  ($qb$S06C07Q09$qb$, $qb$S06$qb$, $qb$C07$qb$, $qb$L+MM$qb$, $qb$Physical or virtual workspace design in your organisation supports focused, deep work:$qb$, $qb$Yes — employees have access to quiet, focused work environments when needed$qb$, $qb$Mostly — focus is possible but the environment is not always conducive to deep work$qb$, $qb$Partially — the work environment frequently interrupts focus and this is acknowledged$qb$, $qb$Poorly — the physical or virtual work environment is a significant barrier to focused, productive work$qb$, 5, 3, 2, 1, true),
  ($qb$S06C07Q10$qb$, $qb$S06$qb$, $qb$C07$qb$, $qb$L+MM+E$qb$, $qb$Overall, the tools, processes, and work design in your organisation enable employees to be:$qb$, $qb$Highly productive — the environment is set up for employees to do their best work$qb$, $qb$Adequately productive — most employees can do their work effectively with some friction$qb$, $qb$Moderately productive — significant friction reduces what employees could otherwise achieve$qb$, $qb$Poorly productive — organisational systems and processes actively inhibit employee effectiveness$qb$, 5, 3, 2, 1, true),
